  "check": {
    "question": "Olivia’s salary has not changed, but she starts paying for health insurance through work. What is the most likely reason her bank deposit gets smaller?",
    "options": [
      {
        "text": "A health insurance deduction is taken from her gross pay.",
        "isCorrect": true,
        "feedback": "Right. The salary can stay the same while a new benefit deduction reduces the amount left for her deposit."
      },
      {
        "text": "Her annual salary is now the same as one paycheck.",
        "isCorrect": false,
        "feedback": "Not quite. Salary is an annual amount; each paycheck is only a portion of it."
