{
  "title": "Why the Sky Looks Blue",
  "screens": [
    {
      "title": "Sunlight holds many colors",
      "text": "On a clear day, sunlight can look white. But it contains a mix of colors, much like light passing through a glass prism and spreading into a rainbow.",
      "imagePrompt": "A beam of white sunlight passing through a glass prism and spreading into bands of rainbow colors"
    },
    {
      "title": "Air scatters blue light",
      "text": "Earth’s air is full of tiny molecules. As sunlight passes through, they redirect its shorter blue and violet wavelengths more than its longer red wavelengths. This is called Rayleigh scattering.",
      "imagePrompt": "Sunlight entering a layer of tiny air molecules, with blue and violet rays redirected in many directions and red rays continuing mostly straight"
    },
    {
      "title": "Blue comes from everywhere",
      "text": "The scattered blue light travels toward your eyes from all across the sky. That’s why the open sky looks blue, rather than like a beam coming from one spot.",
      "imagePrompt": "A person looking upward as blue rays from different parts of the sky travel toward their eyes"
    },
    {
      "title": "Sunsets look different",
      "text": "At sunset, sunlight crosses more air before reaching you. Much of its blue light gets scattered away, so more red and orange light remains in the direct sunlight you see.",
      "imagePrompt": "Sunlight traveling through a long stretch of atmosphere at sunset, with blue rays scattered out and red-orange rays reaching a person"
    },
    {
      "title": "Why not violet?",
      "text": "Air scatters violet too, but sunlight contains less violet than blue, and your eyes are less sensitive to violet. Together, those effects make the sky look blue to you.",
      "imagePrompt": null
    }
  ],
  "check": {
    "question": "You’re looking toward the Sun near sunset. Why might its light look redder than it does at noon?",
    "options": [
      {
        "text": "It travels through more air, which scatters much of the blue light away.",
        "isCorrect": true,
        "feedback": "Right. The longer path through air scatters more blue light away from the direct sunlight."
      },
      {
        "text": "It travels through less air, which scatters most of the red light away.",
        "isCorrect": false,
        "feedback": "Not quite. Near sunset, sunlight crosses more air, and blue light is scattered more than red."
      },
      {
        "text": "The Sun makes only red light when it is near the horizon.",
        "isCorrect": false,
        "feedback": "Not quite. Sunlight contains many colors; the air scatters more blue light from the direct beam."
      },
      {
        "text": "Your eyes become more sensitive to red as the Sun gets lower.",
        "isCorrect": false,
        "feedback": "Not quite. The change comes from sunlight crossing more air, not from your eyes changing."
      }
    ]
  },
  "recap": [
    "Sunlight contains a mix of colors.",
    "Air scatters blue light more than red light.",
    "Scattered blue light makes the sky look blue; longer air paths redden sunsets."
  ],
  "goFurther": {
    "overviewCourse": "Physics",
    "relatedQuestions": [
      "Why does the sky look red at sunrise?",
      "Why do clouds look white?",
      "How does a rainbow form?"
    ]
  }
}

{
  "title": "Como uma vacina protege você",
  "screens": [
    {
      "title": "Um treino antes do jogo",
