  "goFurther": {
    "overviewCourse": "Como o Corpo Humano Funciona",
    "relatedQuestions": [
      "Por que algumas vacinas precisam de reforço?",
      "O que são anticorpos?",
      "Como as vacinas ajudam a proteger uma comunidade?"
